 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);receiveDocument(intent);}
 void receiveDocument(Intent intent){String path=intent.getStringExtra("grafiplot_pdf");if(path==null)return;if(busy||active!=null){setStatus("Hay un trabajo en curso. Espera a que termine antes de cargar otro PDF.");return;}String display=intent.getStringExtra("grafiplot_name");boolean quick=intent.getBooleanExtra("grafiplot_quick_print",false);String requestId=intent.getStringExtra("grafiplot_quick_id");intent.removeExtra("grafiplot_quick_print");if(quick){if(requestId==null||requestId.equals(getPreferences(0).getString("lastQuickId",""))){setStatus("Este envío rápido ya fue procesado. Revisa el estado del trabajo.");return;}getPreferences(0).edit().putString("lastQuickId",requestId).commit();}try{File input=new File(path).getCanonicalFile();File allowed=new File(getCacheDir(),"direct-print").getCanonicalFile();if(!input.getPath().startsWith(allowed.getPath()+File.separator)||!input.isFile()||input.length()>30L*1024*1024)throw new IOException("El documento no es válido");selected=null;pageCount=0;fileLabel.setText("Cargando PDF de Grafiplot…");run(()->{try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(input,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){int count=renderer.getPageCount();if(count<1||count>100)throw new IOException("Solo se admiten PDFs de 1 a 100 páginas");selected=input;pageCount=count;ui(()->{fileLabel.setText((display==null?"Documento Grafiplot":display)+"\n"+count+" página(s)");updateEstimate();});return "PDF recibido de Grafiplot. Revisa las opciones y confirma para enviarlo a la HP.";}},()->{if(quick){mode.setSelection(0);orientation.setSelection(0);color.setSelection(0);copies.setSelection(0);updateEstimate();confirm(true);}});}catch(Exception e){setStatus("No se pudo cargar el PDF: "+e.getMessage());}}
 void ui(Runnable r){runOnUiThread(()->{if(!closed&&!isDestroyed())r.run();});}
 void setStatus(String s){ui(()->status.setText(s));}
 String host(){String s=PrintRules.host(address.getText().toString());getPreferences(0).edit().putString("hostV2",s).apply();return s;}
 void controls(){boolean locked=busy||active!=null;send.setEnabled(!locked&&selected!=null);check.setEnabled(!locked);choose.setEnabled(!locked);view.setEnabled(!locked&&selected!=null);address.setEnabled(!locked);mode.setEnabled(!locked);copies.setEnabled(!locked);color.setEnabled(!locked);orientation.setEnabled(!locked&&mode.getSelectedItemPosition()!=2);cancel.setVisibility(locked?View.VISIBLE:View.GONE);cancel.setEnabled(!cancelPending);progress.setVisibility(locked?View.VISIBLE:View.GONE);}
 void updateEstimate(){if(estimate==null)return;orientation.setEnabled(!busy&&active==null&&mode.getSelectedItemPosition()!=2);if(pageCount==0)return;int sheets=PrintRules.sheets(pageCount,mode.getSelectedItemPosition(),copies.getSelectedItemPosition()+1);estimate.setText(sheets+" hoja(s) en total · máximo 5"+(mode.getSelectedItemPosition()==2?"\nFolleto horizontal · volteo por lado corto":""));estimate.setTextColor(sheets>5?RED:TEAL);}
 interface Task{String run()throws Exception;}
 void run(Task task){run(task,null);}
 void run(Task task,Runnable after){if(busy||active!=null)return;busy=true;stop.set(false);submissionStarted=false;cancelPending=false;controls();status.setText("Preparando…");worker.execute(()->{String result;boolean success=false;try{result=task.run();success=true;}catch(Exception e){if(stop.get()&&active==null)result=submissionStarted?"Envío interrumpido. Revisa la HP: no se puede confirmar la cancelación sin ID de trabajo.":"Operación cancelada. No se envió el documento.";else result="No se completó: "+e.getMessage();if(active!=null)schedulePoll(0);}final String msg=result;final boolean completed=success;ui(()->{busy=false;cancelPending=false;status.setText(msg);controls();if(completed&&after!=null&&!stop.get())after.run();});});}
 static final class Printer{Ipp client;Ipp.Reply caps;Printer(Ipp i,Ipp.Reply c){client=i;caps=c;}}
 static final class JobRef{final Ipp printer;final int id;final String name;JobRef(Ipp p,int id,String name){printer=p;this.id=id;this.name=name;}}
 Printer connect(String name)throws Exception{Exception last=null;String[] names=name.indexOf('.')<0?new String[]{name,name+".local"}:new String[]{name};for(String h:names)for(String path:new String[]{"/ipp/print","/ipp/printer"}){if(stop.get())throw new InterruptedIOException("Cancelado");try{Ipp i=new Ipp(h,path);return new Printer(i,i.capabilities());}catch(IOException e){last=e;}}throw new IOException("No se pudo conectar con "+name+". Verifica el Wi-Fi y el nombre de host. "+(last==null?"":last.getMessage()));}
 void check(){try{String name=host();run(()->{Printer p=connect(name);return "Conectada a: "+p.client.host+"\n"+p.caps.strings("printer-make-and-model")+"\nFormatos: "+p.caps.strings("document-format-supported")+"\nCaras: "+p.caps.strings("sides-supported")+"\nEsta comprobación no imprime.";});}catch(Exception e){status.setText(e.getMessage());}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=7||result!=RESULT_OK||data==null)return;Uri uri=data.getData();selected=null;pageCount=0;fileLabel.setText("Cargando PDF…");run(()->{String name="Documento PDF";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}File f=new File(getCacheDir(),"entrada.pdf");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("No se pudo abrir el PDF");byte[] buf=new byte[32768];long size=0;int n;while((n=in.read(buf))!=-1){if(stop.get())throw new InterruptedIOException("Carga cancelada");size+=n;if(size>30L*1024*1024)throw new IOException("El límite es 30 MB");out.write(buf,0,n);}}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer r=new PdfRenderer(fd)){int count=r.getPageCount();if(count<1||count>100)throw new IOException("Solo se admiten PDFs de 1 a 100 páginas");selected=f;pageCount=count;final String title=name;ui(()->{fileLabel.setText(title+"\n"+count+" páginas");updateEstimate();});return "PDF cargado. Revisa todas las páginas antes de imprimir.";}catch(Exception e){selected=null;f.delete();throw e;}});}
 void preview(){if(selected==null)return;File input=selected;int m=mode.getSelectedItemPosition();boolean landscape=m==2||orientation.getSelectedItemPosition()==1;run(()->{File f=Documents.prepare(input,new File(getCacheDir(),"previa.pdf"),m==2,landscape,stop);ui(()->startActivity(new Intent(this,PreviewActivity.class).putExtra("prepared",f.getAbsolutePath()).putExtra("source",input.getAbsolutePath()).putExtra("mode",m).putExtra("pages",pageCount)));return "Vista previa lista. Puedes recorrer el documento completo y todas las caras preparadas.";});}
 boolean supports(Ipp.Reply r,int op){for(byte[] v:r.values.getOrDefault("operations-supported",Collections.emptyList()))if(v.length==4&&java.nio.ByteBuffer.wrap(v).getInt()==op)return true;return false;}
 void saveJob(JobRef j){active=j;getPreferences(0).edit().putInt("jobId",j.id).putString("jobHost",j.printer.host).putString("jobPath",j.printer.path).putString("jobName",j.name).commit();ui(this::controls);}
 void confirm(){confirm(false);}
 void confirm(boolean direct){if(busy||active!=null||selected==null)return;try{String name=host();int n=copies.getSelectedItemPosition()+1,m=mode.getSelectedItemPosition();PrintRules.enforceLimit(pageCount,m,n);boolean landscape=m==2||orientation.getSelectedItemPosition()==1;String sides=PrintRules.sides(m,landscape),c=color.getSelectedItemPosition()==0?"monochrome":"color";File input=selected;
  if(direct){submit(input,name,n,m,landscape,sides,c);return;}
  new AlertDialog.Builder(this).setTitle("¿Imprimir "+PrintRules.sheets(pageCount,m,n)+" hoja(s)?").setMessage(name+"\n"+mode.getSelectedItem()+" · "+n+" copia(s)\n"+(landscape?"Horizontal · volteo por lado corto":"Vertical · volteo por lado largo")+"\n"+color.getSelectedItem()).setNegativeButton("Volver",null).setPositiveButton("Imprimir",(d,w)->submit(input,name,n,m,landscape,sides,c)).show();
 }catch(Exception e){status.setText(e.getMessage());}}
 void submit(File input,String name,int n,int m,boolean landscape,String sides,String c){run(()->{
   PrintRules.enforceLimit(pageCount,m,n);Printer p=connect(name);boolean pdf=p.caps.has("document-format-supported","application/pdf"),raster=p.caps.has("document-format-supported","image/pwg-raster");if(!pdf&&!raster)throw new IOException("La HP no anuncia PDF ni PWG Raster.");
   if(!p.caps.has("media-supported","iso_a4_210x297mm"))throw new IOException("La HP no anuncia A4.");if(!p.caps.has("sides-supported",sides))throw new IOException("La HP no admite el volteo seleccionado.");if(!p.caps.has("print-color-mode-supported",c))throw new IOException("La HP no anuncia ese modo de color.");
   setStatus("Preparando las páginas…");File ready=Documents.prepare(input,new File(getCacheDir(),"salida.pdf"),m==2,landscape,stop);String format="application/pdf";
   if(!pdf){String type=c.equals("color")?"srgb_8":"sgray_8";if(!p.caps.has("pwg-raster-document-type-supported",type))throw new IOException("Formato PWG de color no admitido: "+type);setStatus("Preparando el archivo para la HP…");ready=Raster.create(ready,new File(getCacheDir(),"salida.pwg"),p.caps,c.equals("color"),sides,landscape,stop);format="image/pwg-raster";}
   if(stop.get())return "Preparación cancelada. No se envió el documento.";
   setStatus("Enviando a "+name+"…");p.client.stop=stop;p.client.jobName="Rapida-"+UUID.randomUUID().toString();boolean created=supports(p.caps,5)&&supports(p.caps,6);
   submissionStarted=true;
   if(created){Ipp.Reply createdJob=p.client.createJob(n,sides,c,format);int id=createdJob.integer("job-id",-1);if(id<=0)throw new IOException("La HP creó el trabajo sin devolver su ID. Revisa la cola de la impresora.");saveJob(new JobRef(new Ipp(p.client.host,p.client.path),id,p.client.jobName));if(stop.get()){requestCancel(active);return "Solicitando cancelación…";}p.client.sendDocument(ready,id,format);}
   else{Ipp.Reply result=p.client.print(ready,n,sides,c,format);int id=result.integer("job-id",-1);if(id<=0)throw new IOException("Envío aceptado sin ID. No se puede confirmar el estado ni cancelar desde la app; revisa la HP.");saveJob(new JobRef(new Ipp(p.client.host,p.client.path),id,p.client.jobName));}
   if(stop.get())requestCancel(active);schedulePoll(0);return stop.get()?"Solicitando cancelación…":"Trabajo enviado. Consultando a la HP…";
  });}
 void cancel(){stop.set(true);cancelPending=true;controls();JobRef j=active;if(j!=null)requestCancel(j);else status.setText("Deteniendo la preparación o el envío… Si ya salió papel, puede ser necesario cancelar también en la HP.");}
 void requestCancel(JobRef j){setStatus("Solicitando cancelación a la HP…");control.execute(()->{try{Ipp.Reply current=j.printer.job(j.id);if(j.name.isEmpty()||!current.has("job-name",j.name))throw new IOException("El ID no se pudo verificar como este trabajo; no se envió la cancelación");j.printer.cancel(j.id);setStatus("Cancelación solicitada. Esperando confirmación de la HP…");}catch(Exception e){setStatus("No se confirmó la cancelación: "+e.getMessage()+". Puedes detener el trabajo desde la pantalla de la HP.");}ui(()->{cancelPending=false;controls();});schedulePoll(500);});}
 void schedulePoll(long delay){handler.post(()->{handler.removeCallbacks(pollTicker);if(!closed&&active!=null)handler.postDelayed(pollTicker,delay);});}
 void pollJob(){JobRef j=active;if(closed||j==null)return;int token=generation;worker.execute(()->{if(active!=j||token!=generation)return;try{Ipp.Reply r=j.printer.job(j.id);if(!j.name.isEmpty()&&!r.strings("job-name").isEmpty()&&!r.has("job-name",j.name)){active=null;generation++;getPreferences(0).edit().remove("jobId").commit();ui(()->{status.setText("El ID ya no corresponde a este documento. Se cerró el seguimiento sin cancelar otros trabajos.");controls();});return;}int state=r.integer("job-state",0);int sheets=r.integer("job-media-sheets-completed",-1);String reasons=String.join(", ",r.strings("job-state-reasons"));String message=PrintRules.state(state)+" · trabajo "+j.id+(sheets>=0?"\nHojas informadas por la HP: "+sheets:"");if(!reasons.isEmpty()&&!reasons.equals("none"))message+="\n"+reasons;
    if(active!=j||token!=generation)return;
    if(PrintRules.terminal(state)){active=null;generation++;getPreferences(0).edit().remove("jobId").commit();final String done=message;ui(()->{cancelPending=false;status.setText(done);controls();});}
    else{setStatus(message);schedulePoll(2500);}
   }catch(Exception e){if(active!=j)return;setStatus("Estado sin confirmar · trabajo "+j.id+"\nNo se puede asegurar que terminó. Reintentando conexión…\n"+e.getMessage());schedulePoll(10000);}
  });}
 @Override protected void onDestroy(){closed=true;handler.removeCallbacksAndMessages(null);worker.shutdown();control.shutdown();super.onDestroy();}
